mapper.select:
SELECT b.cancel_requested,p.enabled AS platform_enabled,a.enabled AS account_enabled,r.enabled,r.auth_paused,
  EXISTS(SELECT 1 FROM daily_completions d WHERE d.request_id=r.id AND d.business_date=#{date}) AS completed,
  EXISTS(SELECT 1 FROM request_day_states d WHERE d.request_id=r.id AND d.business_date=#{date} AND d.unknown_pending=1) AS unknown_pending
FROM run_batches b JOIN platforms p ON p.id=b.platform_id JOIN requests r ON r.id=#{requestId}
JOIN accounts a ON a.id=r.account_id WHERE b.id=#{batchId}
